/** How a field is shown and edited. */
export type FieldKind =
  | "text" | "textarea" | "int" | "decimal" | "money" | "file" | "image" | "bool" | "date" | "datetime"
  | "enum" | "uuid" | "json" | "relation" | "many"

/** A field of a resource, from the model. */
export interface FieldMeta {
  name: string
  label: string
  kind: FieldKind
  required: boolean
  /** An enum's values, and what people call each. */
  values?: readonly string[]
  labels?: Readonly<Record<string, string>>
  /** The color of each value's dot: green, amber, red, blue, violet, sky, orange, gray. */
  colors?: Readonly<Record<string, string>>
  /** How a report's column is shown: a share as a percentage, seconds as a duration. */
  format?: "percent" | "duration"
  /** A relation's resource, and the field its records are shown by. */
  target?: string
  display?: string
  /** What a new record starts with, as the model says. */
  default?: string | number | boolean | { amount: string }
  /** A file field's: what to send it for, its formats and its largest size. */
  upload?: { entity: string; field: string }
  accept?: readonly string[]
  maxSize?: number
  /** A number's bounds, as the model says: min(0). */
  min?: number
  max?: number
  /** A many-to-many relation's: its name in the client (tags), for its links. */
  relation?: string
  /** Formatted text, as HTML (@rest(html)): a rich text editor. */
  rich?: boolean
  /** Shown, never edited (created_at). */
  readOnly?: boolean
  /** An enum with a flow (@store(flow)): a record's can says where it may go, as <field>:<STATE>. */
  flow?: boolean
}

/** A filter of the list, as the API takes it. */
export interface FilterMeta {
  param: string
  kind: string
}

/** A page of a list, as the API answers it. */
export interface Page<T = Rec> {
  items: T[]
  can: string[]
  next?: string
  page?: number
  per_page?: number
  total?: number
  total_pages?: number
}

/** A record, as the API answers it. */
export type Rec = Record<string, unknown> & { id: string; version: number; can?: string[] }

/** The operations of a resource's records, as the API client has them. */
export interface RecordsApi {
  list(query?: Record<string, unknown>, options?: { signal?: AbortSignal }): Promise<Page>
  get(id: string, selection?: Record<string, unknown>, options?: { signal?: AbortSignal }): Promise<Rec>
  create(record: Record<string, unknown>, options?: { idempotencyKey?: string }): Promise<Rec>
  update(id: string, record: Record<string, unknown>, options?: { ifMatch?: number | { version: number } }): Promise<Rec>
  patch(id: string, changes: Record<string, unknown>, options?: { ifMatch?: number | { version: number } }): Promise<Rec>
  delete(id: string, options?: { ifMatch?: number | { version: number } }): Promise<void>
  /** Where delete puts records, when their entity has a trash. */
  trash?: TrashApi
  /** Stores rows, all or none, when the entity takes imports. */
  import?(rows: Record<string, unknown>[], options?: { idempotencyKey?: string }): Promise<{ created: number; updated: number }>
}

/** The trash of a resource whose entity has one. */
export interface TrashApi {
  list(query?: { page?: number; per_page?: number }, options?: { signal?: AbortSignal }): Promise<Page>
  restore(id: string): Promise<Rec>
  purge(id: string): Promise<void>
  empty(): Promise<{ purged: number }>
}

/** A resource as the model says it: generated in resources.gen.ts. */
export interface ResourceMeta<F extends Record<string, FieldMeta> = Record<string, FieldMeta>> {
  name: string
  label: string
  singular: string
  menu: string
  icon: string
  /** The field a record is called by: name. */
  title: string
  api: (api: never) => RecordsApi
  fields: F
  filters: readonly FilterMeta[]
  sorts: readonly string[]
  /** The orders worked out by an expression (@store(order)), largest first: sort=<name>. By page only. */
  orders?: readonly { name: string; label: string }[]
  pagination: readonly string[]
  /** Deleting puts records in the trash, where they stay days days (0: until emptied). */
  trash?: { days: number }
  /** Its changes are kept (the audit blueprint): its plural, and who sees a record's history. */
  history?: { entity: string; who: "update" | "read" | "admins" }
  /** One record only (@store(single)): its page is its form, with no list. */
  single?: boolean
  /** Its records may be imported from a CSV file (@store(import)); by: the field a row replaces the record of. */
  import?: { by?: string }
}

export function defineMeta<const F extends Record<string, FieldMeta>, A>(
  meta: Omit<ResourceMeta<F>, "api"> & { api: (api: A) => RecordsApi },
): ResourceMeta<F> {
  return meta as unknown as ResourceMeta<F>
}

/** The id of the one record of a single resource. */
export const singleId = "00000000-0000-0000-0000-000000000001"

/** The operations of a single entity, as the API client has them. */
interface SingleApi {
  get(selection?: Record<string, unknown>, options?: { signal?: AbortSignal }): Promise<Rec>
  update(record: Record<string, unknown>, options?: { ifMatch?: number | { version: number } }): Promise<Rec>
  patch(changes: Record<string, unknown>, options?: { ifMatch?: number | { version: number } }): Promise<Rec>
  history?(query: object, options: object): Promise<unknown>
}

/**
 * A single entity's operations as those of a resource's records, so that
 * its form reads and saves it as any other: the id is its one record's.
 * It has no list, create or delete.
 */
export function singleRecords(one: unknown): RecordsApi {
  const s = one as SingleApi
  const none = () => Promise.reject(new Error("a single resource has one record only"))
  return {
    list: none,
    get: (_id, selection, options) => s.get(selection, options),
    create: none,
    update: (_id, record, options) => s.update(record, options),
    patch: (_id, changes, options) => s.patch(changes, options),
    delete: none,
    ...(s.history && { history: (_id: string, query: object, options: object) => s.history!(query, options) }),
  } as RecordsApi
}

